from .ranges import bounds, RangeSyntaxError


def serve(data, range_header=None):
    length = len(data)
    if range_header is None:
        return 200, {'Content-Length': str(length)}, data

    try:
        head, tail = bounds(range_header)
    except RangeSyntaxError:
        return _not_satisfiable(length)

    if length == 0:
        return _not_satisfiable(length)

    if head is None:
        # `bytes=-N`: the final N bytes
        if tail == 0:
            return _not_satisfiable(length)
        start, end = max(0, length - tail), length - 1
    else:
        # `bytes=start-end` or `bytes=start-`; end is inclusive, clamped to EOF
        end = min(tail if tail is not None else length - 1, length - 1)
        if head > end:
            return _not_satisfiable(length)
        start = head

    body = data[start:end + 1]
    return 206, {'Content-Length': str(len(body)),
                 'Content-Range': f'bytes {start}-{end}/{length}'}, body


def _not_satisfiable(length):
    return 416, {'Content-Range': f'bytes */{length}'}, b''
